/**
 * Content Credentials (C2PA) reader.
 *
 * Content Credentials are a signed record that a camera, an AI tool or an editing program can embed
 * in a photo: who made it, what tools touched it, and whether it was generated by AI. This module
 * reads them from JPEG photos and checks what can be checked without any outside service:
 *
 *   1. the signature over the credential is valid for the certificate it carries,
 *   2. the credential's own parts have not been altered (assertion hashes),
 *   3. the photo's pixels are the same bytes that were signed (the hard-binding hash).
 *
 * What it does NOT do: it does not check the signer's certificate against a list of trusted signers
 * (trust_list_checked is always false). Anyone can make a certificate with any name on it, so "intact"
 * means "the file matches what its own credential signed", NOT "made by the named signer" or "made by
 * a trusted camera". The signer name is a claim. A credential also only shows a file's declared
 * history; it does not prove the scene is true, and most photos carry no credential at all (platforms
 * often strip them), so a missing credential proves nothing. The reliable uses are the adverse ones:
 * a credential that declares AI generation, and a credential that no longer matches its photo.
 *
 * No native code and no network. Pure JavaScript plus Node's built-in crypto.
 * Supported containers: JPEG. Anything else returns null (not read).
 */

import crypto from "crypto";

const MAX_JUMBF_BYTES = 8 * 1024 * 1024;
const AI_SOURCE_TYPES = new Set(["trainedAlgorithmicMedia", "compositeWithTrainedAlgorithmicMedia"]);
const HASH_ALGS = { sha256: "sha256", sha384: "sha384", sha512: "sha512", "SHA-256": "sha256", "SHA-384": "sha384", "SHA-512": "sha512" };

/* ---------------------------------- minimal CBOR ---------------------------------- */

class Tagged {
  constructor(tag, value) { this.tag = tag; this.value = value; }
}

function readCbor(buf, state, depth = 0) {
  if (depth > 40) throw new Error("cbor too deep");
  if (++state.items > 200000) throw new Error("cbor too large");
  if (state.pos >= buf.length) throw new Error("cbor truncated");
  const initial = buf[state.pos++];
  const major = initial >> 5;
  const ai = initial & 31;

  const readArg = () => {
    if (ai < 24) return ai;
    const sizes = { 24: 1, 25: 2, 26: 4, 27: 8 };
    const n = sizes[ai];
    if (!n) throw new Error("cbor bad length");
    if (state.pos + n > buf.length) throw new Error("cbor truncated");
    let v;
    if (n === 1) v = buf.readUInt8(state.pos);
    else if (n === 2) v = buf.readUInt16BE(state.pos);
    else if (n === 4) v = buf.readUInt32BE(state.pos);
    else v = Number(buf.readBigUInt64BE(state.pos));
    state.pos += n;
    return v;
  };

  if (major === 7) {
    if (ai === 20) return false;
    if (ai === 21) return true;
    if (ai === 22) return null;
    if (ai === 23) return undefined;
    if (ai === 25) { // half float
      const h = buf.readUInt16BE(state.pos); state.pos += 2;
      const e = (h >> 10) & 31, m = h & 1023;
      const v = e === 0 ? m * 2 ** -24 : e !== 31 ? (m + 1024) * 2 ** (e - 25) : m ? NaN : Infinity;
      return h & 0x8000 ? -v : v;
    }
    if (ai === 26) { const v = buf.readFloatBE(state.pos); state.pos += 4; return v; }
    if (ai === 27) { const v = buf.readDoubleBE(state.pos); state.pos += 8; return v; }
    if (ai === 31) throw new Error("cbor unexpected break");
    return ai; // simple value
  }

  if (ai === 31) { // indefinite length
    if (major === 4 || major === 5) {
      const out = major === 4 ? [] : new Map();
      while (buf[state.pos] !== 0xff) {
        if (state.pos >= buf.length) throw new Error("cbor truncated");
        if (major === 4) out.push(readCbor(buf, state, depth + 1));
        else { const k = readCbor(buf, state, depth + 1); out.set(k, readCbor(buf, state, depth + 1)); }
      }
      state.pos++;
      return out;
    }
    if (major === 2 || major === 3) {
      const chunks = [];
      while (buf[state.pos] !== 0xff) {
        if (state.pos >= buf.length) throw new Error("cbor truncated");
        chunks.push(readCbor(buf, state, depth + 1));
      }
      state.pos++;
      return major === 2 ? Buffer.concat(chunks) : chunks.join("");
    }
    throw new Error("cbor bad indefinite");
  }

  const arg = readArg();
  switch (major) {
    case 0: return arg;
    case 1: return -1 - arg;
    case 2: {
      if (state.pos + arg > buf.length) throw new Error("cbor truncated");
      const v = buf.subarray(state.pos, state.pos + arg); state.pos += arg; return v;
    }
    case 3: {
      if (state.pos + arg > buf.length) throw new Error("cbor truncated");
      const v = buf.toString("utf8", state.pos, state.pos + arg); state.pos += arg; return v;
    }
    case 4: {
      if (arg > buf.length) throw new Error("cbor bad array");
      const out = [];
      for (let i = 0; i < arg; i++) out.push(readCbor(buf, state, depth + 1));
      return out;
    }
    case 5: {
      if (arg > buf.length) throw new Error("cbor bad map");
      const out = new Map();
      for (let i = 0; i < arg; i++) { const k = readCbor(buf, state, depth + 1); out.set(k, readCbor(buf, state, depth + 1)); }
      return out;
    }
    case 6: return new Tagged(arg, readCbor(buf, state, depth + 1));
    default: throw new Error("cbor unsupported");
  }
}

export function decodeCbor(buf) {
  const state = { pos: 0, items: 0 };
  return readCbor(buf, state);
}

function cborHead(major, n) {
  if (n < 24) return Buffer.from([(major << 5) | n]);
  if (n < 256) return Buffer.from([(major << 5) | 24, n]);
  if (n < 65536) { const b = Buffer.alloc(3); b[0] = (major << 5) | 25; b.writeUInt16BE(n, 1); return b; }
  const b = Buffer.alloc(5); b[0] = (major << 5) | 26; b.writeUInt32BE(n, 1); return b;
}
const cborBytes = (buf) => Buffer.concat([cborHead(2, buf.length), buf]);
const cborText = (s) => { const b = Buffer.from(s, "utf8"); return Buffer.concat([cborHead(3, b.length), b]); };

// A map's values by key whether the map came from text or integer keys.
const mget = (m, k) => (m instanceof Map ? m.get(k) : undefined);

/* ---------------------------------- JUMBF ---------------------------------- */

function readBoxes(buf, start, end) {
  const boxes = [];
  let off = start;
  while (end - off >= 8) {
    let size = buf.readUInt32BE(off);
    const type = buf.toString("latin1", off + 4, off + 8);
    let header = 8;
    if (size === 1) {
      if (end - off < 16) break;
      size = Number(buf.readBigUInt64BE(off + 8));
      header = 16;
    } else if (size === 0) {
      size = end - off;
    }
    if (size < header || off + size > end) break;
    boxes.push({ type, start: off, end: off + size, payloadStart: off + header });
    off += size;
  }
  return boxes;
}

// A JUMBF superbox: a description box (label) followed by content boxes or nested superboxes.
function readSuperbox(buf, box) {
  const children = readBoxes(buf, box.payloadStart, box.end);
  const desc = children.find((c) => c.type === "jumd");
  if (!desc || desc.end - desc.payloadStart < 17) return null;
  const toggles = buf[desc.payloadStart + 16];
  let labelEnd = desc.payloadStart + 17;
  while (labelEnd < desc.end && buf[labelEnd] !== 0) labelEnd++;
  const label = buf.toString("utf8", desc.payloadStart + 17, labelEnd);
  return {
    label,
    uuid: buf.subarray(desc.payloadStart, desc.payloadStart + 16).toString("hex"),
    hasLabel: !!(toggles & 2),
    box,
    // Hashes in a claim cover the superbox contents: the description box and everything after it.
    contentBytes: buf.subarray(box.payloadStart, box.end),
    kids: children.filter((c) => c !== desc),
    buf,
  };
}

function childSupers(sb) {
  return sb.kids.filter((k) => k.type === "jumb").map((k) => readSuperbox(sb.buf, k)).filter(Boolean);
}

function firstContent(sb, type) {
  const k = sb.kids.find((c) => c.type === type);
  return k ? sb.buf.subarray(k.payloadStart, k.end) : null;
}

/* ---------------------------------- JPEG ---------------------------------- */

// Collect the JUMBF data from a JPEG's APP11 segments, and the byte ranges those segments occupy.
function extractJpegJumbf(buf) {
  if (buf.length < 4 || buf[0] !== 0xff || buf[1] !== 0xd8) return null;
  const groups = new Map(); // box instance (En) -> [{z, data, start, length}]
  let off = 2;
  while (off + 4 <= buf.length) {
    if (buf[off] !== 0xff) break;
    while (buf[off + 1] === 0xff) off++;
    const marker = buf[off + 1];
    if (marker === 0xd9 || marker === 0xda) break;
    if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) { off += 2; continue; }
    const len = buf.readUInt16BE(off + 2);
    if (len < 2 || off + 2 + len > buf.length) break;
    if (marker === 0xeb && len >= 10 && buf[off + 4] === 0x4a && buf[off + 5] === 0x50) {
      const en = buf.readUInt16BE(off + 6);
      const z = buf.readUInt32BE(off + 8);
      const list = groups.get(en) || [];
      list.push({ z, data: buf.subarray(off + 12, off + 2 + len), start: off, length: 2 + len });
      groups.set(en, list);
    }
    off += 2 + len;
  }
  const out = [];
  for (const list of groups.values()) {
    list.sort((a, b) => a.z - b.z);
    // The first segment holds the whole box header; each later one repeats the 8-byte
    // length and type before its slice of the content.
    const parts = list.map((seg, i) => (i === 0 ? seg.data : seg.data.subarray(8)));
    const total = parts.reduce((n, p) => n + p.length, 0);
    if (total > MAX_JUMBF_BYTES) continue;
    out.push({ data: Buffer.concat(parts), ranges: list.map((s) => ({ start: s.start, length: s.length })) });
  }
  return out;
}

/* ---------------------------------- checks ---------------------------------- */

function hashWith(alg, ...chunks) {
  const h = crypto.createHash(alg);
  for (const c of chunks) h.update(c);
  return h.digest();
}

function algOf(value, fallback) {
  return HASH_ALGS[value] || fallback;
}

function labelFromUrl(url) {
  return typeof url === "string" ? url.split("/").pop() : null;
}

function verifyCoseSignature(sign1, claimBytes) {
  const parts = sign1 instanceof Tagged ? sign1.value : sign1;
  if (!Array.isArray(parts) || parts.length !== 4) throw new Error("signature is not a COSE_Sign1");
  const [protectedBytes, unprotected, , signature] = parts;
  const protectedMap = protectedBytes.length ? decodeCbor(protectedBytes) : new Map();
  const alg = mget(protectedMap, 1);
  let chain = mget(protectedMap, 33) ?? mget(unprotected, 33);
  if (!chain) throw new Error("no certificate in the signature");
  if (Buffer.isBuffer(chain)) chain = [chain];
  const certs = chain.map((der) => new crypto.X509Certificate(der));
  const publicKey = certs[0].publicKey;

  const toBeSigned = Buffer.concat([Buffer.from([0x84]), cborText("Signature1"), cborBytes(protectedBytes), cborBytes(Buffer.alloc(0)), cborBytes(claimBytes)]);
  let ok;
  switch (alg) {
    case -7: ok = crypto.verify("sha256", toBeSigned, { key: publicKey, dsaEncoding: "ieee-p1363" }, signature); break;
    case -35: ok = crypto.verify("sha384", toBeSigned, { key: publicKey, dsaEncoding: "ieee-p1363" }, signature); break;
    case -36: ok = crypto.verify("sha512", toBeSigned, { key: publicKey, dsaEncoding: "ieee-p1363" }, signature); break;
    case -37: case -38: case -39: {
      const hash = { "-37": "sha256", "-38": "sha384", "-39": "sha512" }[String(alg)];
      ok = crypto.verify(hash, toBeSigned, { key: publicKey, padding: crypto.constants.RSA_PKCS1_PSS_PADDING, saltLength: crypto.constants.RSA_PSS_SALTLEN_DIGEST }, signature);
      break;
    }
    case -8: ok = crypto.verify(null, toBeSigned, publicKey, signature); break;
    default: throw new Error(`unsupported signature algorithm ${alg}`);
  }

  // The certificates in the chain should each be signed by the next. This does not say the root is
  // trusted, only that the chain the file carries is internally consistent.
  let chainConsistent = true;
  for (let i = 0; i < certs.length - 1; i++) {
    try { if (!certs[i].verify(certs[i + 1].publicKey)) chainConsistent = false; } catch { chainConsistent = false; }
  }
  return { ok: !!ok, certs, chainConsistent };
}

function subjectField(cert, field) {
  const m = new RegExp(`(?:^|\\n)${field}=([^\\n]+)`).exec(cert.subject || "");
  return m ? m[1] : null;
}

function describeAgent(agent) {
  if (!agent) return null;
  if (typeof agent === "string") return agent;
  if (agent instanceof Map) {
    const name = agent.get("name");
    const version = agent.get("version");
    return name ? (version ? `${name} ${version}` : String(name)) : null;
  }
  return null;
}

function stripSourceType(uri) {
  return typeof uri === "string" ? uri.split("/").pop() : null;
}

/* ---------------------------------- main ---------------------------------- */

/**
 * readContentCredentials(buffer)
 *
 * Returns null if the file is not a JPEG (not read). Otherwise:
 * {
 *   status: 'none' | 'intact' | 'invalid' | 'unverified',
 *   reason: string | null,          // why invalid / unverified
 *   signer: { name, organization, issuer } | null,
 *   generator: string | null,       // the tool that made the credential
 *   title: string | null,
 *   source_type: string | null,     // e.g. 'digitalCapture', 'trainedAlgorithmicMedia'
 *   ai_declared: boolean,           // the credential (or an earlier version of the photo) says AI made it
 *   actions: string[],              // e.g. ['created', 'edited']
 *   manifests: number,
 *   trust_list_checked: false,
 *   chain_consistent: boolean | null
 * }
 */
export function readContentCredentials(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 4 || buffer[0] !== 0xff || buffer[1] !== 0xd8) return null;

  const base = { status: "none", reason: null, signer: null, generator: null, title: null, source_type: null, ai_declared: false, actions: [], manifests: 0, trust_list_checked: false, chain_consistent: null };

  let jumbfs;
  try { jumbfs = extractJpegJumbf(buffer); } catch { return { ...base, status: "unverified", reason: "The credential data in this photo could not be read." }; }
  if (!jumbfs || jumbfs.length === 0) return base;

  try {
    // Find the manifest store: the superbox labeled "c2pa".
    let store = null, ranges = [];
    for (const j of jumbfs) {
      const top = readBoxes(j.data, 0, j.data.length).filter((b) => b.type === "jumb");
      for (const t of top) {
        const sb = readSuperbox(j.data, t);
        if (sb && sb.label === "c2pa") { store = sb; ranges = j.ranges; break; }
      }
      if (store) break;
    }
    if (!store) return base;

    const manifests = childSupers(store);
    if (manifests.length === 0) return { ...base, status: "unverified", reason: "This photo has a credential store but no credentials in it." };

    // Everything the credentials declare, across the photo's whole history.
    const out = { ...base, manifests: manifests.length };
    const actionNames = new Set();
    let sourceType = null;
    for (const m of manifests) {
      const parts = childSupers(m);
      const assertionsBox = parts.find((p) => p.label === "c2pa.assertions");
      const assertions = assertionsBox ? childSupers(assertionsBox) : [];
      for (const a of assertions) {
        if (!/^c2pa\.actions(\.v2)?(__\d+)?$/.test(a.label)) continue;
        const data = firstContent(a, "cbor");
        if (!data) continue;
        const parsed = decodeCbor(data);
        const list = [...(mget(parsed, "actions") || []), ...(mget(parsed, "templates") || [])];
        for (const act of list) {
          const name = mget(act, "action");
          if (typeof name === "string") actionNames.add(name.replace(/^c2pa\./, ""));
          const st = stripSourceType(mget(act, "digitalSourceType"));
          if (st) {
            if (AI_SOURCE_TYPES.has(st)) out.ai_declared = true;
            // The photo's own origin: what its active (last) manifest says it was created as.
            if (m === manifests[manifests.length - 1] && (!sourceType || name === "c2pa.created")) sourceType = st;
          }
        }
      }
    }
    out.actions = [...actionNames];
    out.source_type = sourceType;

    // Check the active (last) manifest.
    const active = manifests[manifests.length - 1];
    const parts = childSupers(active);
    const claimBox = parts.find((p) => p.label === "c2pa.claim" || p.label === "c2pa.claim.v2");
    const sigBox = parts.find((p) => p.label === "c2pa.signature");
    const assertionsBox = parts.find((p) => p.label === "c2pa.assertions");
    if (!claimBox || !sigBox) return { ...out, status: "unverified", reason: "The credential is missing its claim or signature." };

    const claimBytes = firstContent(claimBox, "cbor");
    const sigBytes = firstContent(sigBox, "cbor");
    if (!claimBytes || !sigBytes) return { ...out, status: "unverified", reason: "The credential is missing its claim or signature." };
    const claim = decodeCbor(claimBytes);

    const gen = describeAgent(mget(claim, "claim_generator_info")?.[0]) || (typeof mget(claim, "claim_generator") === "string" ? mget(claim, "claim_generator") : null);
    out.generator = gen ? gen.slice(0, 80) : null;
    const title = mget(claim, "dc:title");
    out.title = typeof title === "string" ? title.slice(0, 120) : null;

    // 1. Signature over the claim.
    let sig;
    try {
      sig = verifyCoseSignature(decodeCbor(sigBytes), claimBytes);
    } catch (err) {
      return { ...out, status: "unverified", reason: `The signature could not be checked (${err.message}).` };
    }
    const leaf = sig.certs[0];
    out.signer = {
      name: subjectField(leaf, "CN"),
      organization: subjectField(leaf, "O"),
      issuer: subjectField({ subject: leaf.issuer }, "O") || subjectField({ subject: leaf.issuer }, "CN"),
    };
    out.chain_consistent = sig.chainConsistent;
    if (!sig.ok) return { ...out, status: "invalid", reason: "The credential's signature does not check out, so it may have been altered." };
    if (!sig.chainConsistent) return { ...out, status: "invalid", reason: "The signer's certificate in the credential has been altered." };

    // 2. Each assertion the claim lists still matches its recorded hash.
    const claimAlg = algOf(mget(claim, "alg"), "sha256");
    const refs = [...(mget(claim, "assertions") || []), ...(mget(claim, "created_assertions") || []), ...(mget(claim, "gathered_assertions") || [])];
    const byLabel = new Map((assertionsBox ? childSupers(assertionsBox) : []).map((a) => [a.label, a]));
    for (const ref of refs) {
      const label = labelFromUrl(mget(ref, "url"));
      const expected = mget(ref, "hash");
      const a = byLabel.get(label);
      if (!a || !Buffer.isBuffer(expected)) return { ...out, status: "invalid", reason: "A part of the credential the signature covers is missing." };
      const alg = algOf(mget(ref, "alg"), claimAlg);
      if (!hashWith(alg, a.contentBytes).equals(expected)) return { ...out, status: "invalid", reason: "A part of the credential was changed after it was signed." };
    }

    // 3. The photo's pixels are the same bytes that were signed.
    const binding = [...byLabel.entries()].find(([label]) => /^c2pa\.hash\.data(__\d+)?$/.test(label));
    if (!binding) return { ...out, status: "unverified", reason: "This credential uses a method of tying itself to the photo that ProofDeed does not check yet." };
    const bd = decodeCbor(firstContent(binding[1], "cbor"));
    const expected = mget(bd, "hash");
    const exclusions = (mget(bd, "exclusions") || []).map((e) => ({ start: mget(e, "start"), length: mget(e, "length") })).sort((a, b) => a.start - b.start);
    if (!Buffer.isBuffer(expected) || exclusions.some((e) => !Number.isFinite(e.start) || !Number.isFinite(e.length))) {
      return { ...out, status: "unverified", reason: "This credential's photo binding could not be read." };
    }
    const alg = algOf(mget(bd, "alg"), claimAlg);
    const h = crypto.createHash(alg);
    let pos = 0;
    for (const e of exclusions) {
      if (e.start < pos || e.start + e.length > buffer.length) return { ...out, status: "invalid", reason: "The credential's record of the photo does not fit this file." };
      h.update(buffer.subarray(pos, e.start));
      pos = e.start + e.length;
    }
    h.update(buffer.subarray(pos));
    if (!h.digest().equals(expected)) return { ...out, status: "invalid", reason: "The photo was changed after the credential was signed." };

    return { ...out, status: "intact", reason: null };
  } catch (err) {
    return { ...base, status: "unverified", reason: "The credential data in this photo could not be read." };
  }
}

/**
 * A plain-language line for a result, for the record page, emails and reports.
 * Always says what it does not prove.
 */
export function describeContentCredentials(cc) {
  if (!cc) return null;
  const who = cc.signer?.organization || cc.signer?.name || null;
  const tool = cc.generator ? ` Tool named in the credential: ${cc.generator}.` : "";
  const fine = " Content Credentials show a photo's declared history; they do not prove the scene is true.";
  switch (cc.status) {
    case "intact":
      return {
        headline: cc.ai_declared ? "Content Credentials say this photo was made with AI" : "Content Credentials found, and the photo matches them",
        detail: `${cc.ai_declared ? "The credential declares AI generation. " : "The photo is unchanged since the credential was signed. "}${who ? `It names ${who} as the signer, but ProofDeed has not confirmed that signer is trusted, so treat the name as a claim.` : "ProofDeed has not confirmed who signed it."}${tool}${fine}`,
      };
    case "invalid":
      return {
        headline: "Content Credentials found, but they do not check out",
        detail: `${cc.reason || "They failed verification."}${cc.ai_declared ? " They also declare AI generation." : ""} Treat any claim they make with caution.`,
      };
    case "unverified":
      return {
        headline: "Content Credentials found, but not fully checked",
        detail: `${cc.reason || "ProofDeed could not complete the check."}${cc.ai_declared ? " They declare AI generation." : ""}`,
      };
    default:
      return { headline: "No Content Credentials in this photo", detail: "Most photos have none, and sharing sites often remove them, so this says nothing either way." };
  }
}
